type Tickable interface{ Tick() }

type Ball struct {
    GameItem                    // embedded: fields and methods are promoted
    suspended bool
    onTick    func()            // callback instead of a second twin object
}
func (b *Ball) Draw()  { ... }
func (b *Ball) Click() { b.suspended = !b.suspended }
func (b *Ball) Tick()  { if !b.suspended { b.Draw(); b.onTick() } }
var _ GameItem = (*Ball)(nil)   // static assertions replace upcasts
var _ Tickable = (*Ball)(nil)
